package com.agencytrip.agencytripapi.infrastructure.adapter.in.web;
import com.agencytrip.agencytripapi.application.service.UserService; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import java.util.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@Tag(name="Administración") @RestController public class AdminController {private final UserService users;public AdminController(UserService u){users=u;}@Operation(summary="Listar roles",security=@SecurityRequirement(name="bearerAuth"))@GetMapping("/api/Roles")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object roles(){return users.roles();}@Operation(summary="Consultar panel administrativo",security=@SecurityRequirement(name="bearerAuth"))@GetMapping("/api/Admin/panel")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object panel(){return Map.of("mensaje","Acceso autorizado al panel de administrador.","rol","ADMINISTRADOR");}}
